"use client";

import * as React from "react";
import { StarIcon } from "@hugeicons/core-free-icons";
import { type IconSvgElement } from "@hugeicons/react";
import { HaloIcon } from "@/components/icons/halo-icon";
import { cn } from "@/lib/utils";
import { useFieldControlProps, useFieldContext } from "@/components/ui/field";

/* -------------------------------------------------------------------------- */
/* RatingInput Context                                                        */
/* -------------------------------------------------------------------------- */

interface RatingInputContextValue {
  value: number | null;
  hoveredValue: number | null;
  max: number;
  disabled: boolean;
  readOnly: boolean;
  size: "sm" | "md" | "lg";
  focusedIndex: number | null;
  icon?: IconSvgElement;
  onItemSelect: (val: number) => void;
  onItemHover: (val: number) => void;
  onItemHoverLeave: () => void;
  onItemFocus: (val: number) => void;
  onItemBlur: () => void;
}

const RatingInputContext = React.createContext<RatingInputContextValue | null>(null);

export function useRatingInputContext() {
  const context = React.useContext(RatingInputContext);
  if (!context) {
    throw new Error("RatingInput compound components must be rendered inside a <RatingInput />");
  }
  return context;
}

/* -------------------------------------------------------------------------- */
/* Types & Interfaces                                                         */
/* -------------------------------------------------------------------------- */

export type RatingSize = "sm" | "md" | "lg";

export interface RatingInputProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  /**
   * The controlled rating value (1 to max, or null for empty).
   */
  value?: number | null;
  /**
   * The initial uncontrolled rating value.
   */
  defaultValue?: number | null;
  /**
   * Callback fired when a rating score is committed.
   */
  onValueChange?: (value: number) => void;
  /**
   * Maximum score on the scale.
   * @default 5
   */
  max?: number;
  /**
   * Size of rating items and touch targets.
   * @default "md"
   */
  size?: RatingSize;
  /**
   * Whether the rating input is disabled.
   */
  disabled?: boolean;
  /**
   * Whether the rating input is read-only.
   * Note: For display-only ratings, use RatingDisplay rather than read-only RatingInput.
   */
  readOnly?: boolean;
  /**
   * Whether the rating input is invalid.
   */
  invalid?: boolean;
  /**
   * Whether a selection is required.
   */
  required?: boolean;
  /**
   * Custom icon element from Hugeicons.
   * @default StarIcon
   */
  icon?: IconSvgElement;
  /**
   * Descriptive labels for each score index (1-based), e.g. ["Poor", "Fair", "Good", "Very Good", "Excellent"].
   */
  labels?: string[];
  /**
   * Accessible name generator for each rating item.
   */
  getItemAriaLabel?: (itemValue: number, max: number, label?: string) => string;
}

/* -------------------------------------------------------------------------- */
/* RatingInput Root                                                           */
/* -------------------------------------------------------------------------- */

/**
 * RatingInput — Forms & Fields Primitive 28
 *
 * An accessible single-value rating control for choosing a score from an ordered icon-based scale.
 * Implements W3C radio-group semantics, roving focus, cumulative visual fill, and temporary hover preview.
 */
export const RatingInput = React.forwardRef<HTMLDivElement, RatingInputProps>(
  function RatingInput(
    {
      value: controlledValue,
      defaultValue = null,
      onValueChange,
      max = 5,
      size = "md",
      disabled: propDisabled,
      readOnly = false,
      invalid: propInvalid,
      required: propRequired,
      icon = StarIcon,
      labels,
      getItemAriaLabel,
      className,
      id: propId,
      "aria-label": ariaLabel,
      "aria-labelledby": ariaLabelledBy,
      onKeyDown: propOnKeyDown,
      children,
      ...props
    },
    ref
  ) {
    const fieldProps = useFieldControlProps({
      id: propId,
      disabled: propDisabled,
      required: propRequired,
      "aria-invalid": propInvalid,
    });

    const fieldContext = useFieldContext();
    const isDisabled = Boolean(propDisabled || fieldProps.disabled);
    const isInvalid = Boolean(propInvalid || fieldProps["aria-invalid"]);
    const isRequired = Boolean(propRequired || fieldProps.required);

    // Controlled vs Uncontrolled value state
    const [internalValue, setInternalValue] = React.useState<number | null>(defaultValue);
    const isControlled = controlledValue !== undefined;
    const committedValue = isControlled ? controlledValue : internalValue;

    // Temporary hover preview state (never commits until activation)
    const [hoveredValue, setHoveredValue] = React.useState<number | null>(null);

    // Coordinated keyboard roving focus state
    const [focusedIndex, setFocusedIndex] = React.useState<number | null>(null);
    const containerRef = React.useRef<HTMLDivElement | null>(null);

    // Determine which item receives roving tabIndex={0}
    // If a value is selected, that value is the active tab stop; otherwise item 1
    const activeTabIndex = committedValue ? committedValue : 1;

    const commitRating = React.useCallback(
      (newRating: number) => {
        if (isDisabled || readOnly) return;
        const clamped = Math.max(1, Math.min(max, newRating));
        if (!isControlled) {
          setInternalValue(clamped);
        }
        onValueChange?.(clamped);
      },
      [isDisabled, isControlled, max, onValueChange, readOnly]
    );

    const handleItemHover = React.useCallback(
      (rating: number) => {
        if (isDisabled || readOnly) return;
        setHoveredValue(rating);
      },
      [isDisabled, readOnly]
    );

    const handleItemHoverLeave = React.useCallback(() => {
      setHoveredValue(null);
    }, []);

    const handleItemFocus = React.useCallback((rating: number) => {
      setFocusedIndex(rating);
    }, []);

    const handleItemBlur = React.useCallback(() => {
      setFocusedIndex(null);
    }, []);

    // Coordinated Arrow navigation across radio items
    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      propOnKeyDown?.(e);
      if (isDisabled || readOnly) return;

      const current = focusedIndex ?? committedValue ?? 1;
      let target: number | null = null;

      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          e.preventDefault();
          target = current < max ? current + 1 : current;
          break;
        case "ArrowLeft":
        case "ArrowDown":
          e.preventDefault();
          target = current > 1 ? current - 1 : current;
          break;
        case "Home":
          e.preventDefault();
          target = 1;
          break;
        case "End":
          e.preventDefault();
          target = max;
          break;
        case " ":
        case "Enter":
          e.preventDefault();
          if (focusedIndex !== null) {
            commitRating(focusedIndex);
          }
          return;
      }

      if (target !== null) {
        setFocusedIndex(target);
        commitRating(target);
        // Focus the corresponding item button
        const itemEl = containerRef.current?.querySelector<HTMLButtonElement>(
          `[data-rating-value="${target}"]`
        );
        itemEl?.focus();
      }
    };

    const contextValue = React.useMemo<RatingInputContextValue>(
      () => ({
        value: committedValue,
        hoveredValue,
        max,
        disabled: isDisabled,
        readOnly,
        size,
        focusedIndex,
        icon,
        onItemSelect: commitRating,
        onItemHover: handleItemHover,
        onItemHoverLeave: handleItemHoverLeave,
        onItemFocus: handleItemFocus,
        onItemBlur: handleItemBlur,
      }),
      [
        committedValue,
        hoveredValue,
        max,
        isDisabled,
        readOnly,
        size,
        focusedIndex,
        icon,
        commitRating,
        handleItemHover,
        handleItemHoverLeave,
        handleItemFocus,
        handleItemBlur,
      ]
    );

    // Items array 1..max
    const items = React.useMemo(() => {
      return Array.from({ length: max }, (_, i) => i + 1);
    }, [max]);

    const effectiveLabelledBy = ariaLabelledBy || fieldContext?.labelId;
    const defaultGroupLabel = !ariaLabel && !effectiveLabelledBy ? "Rating" : undefined;

    return (
      <RatingInputContext.Provider value={contextValue}>
        <div
          ref={(node) => {
            containerRef.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) ref.current = node;
          }}
          role="radiogroup"
          aria-label={ariaLabel || defaultGroupLabel}
          aria-labelledby={effectiveLabelledBy}
          aria-describedby={fieldProps["aria-describedby"]}
          aria-invalid={isInvalid ? "true" : undefined}
          aria-required={isRequired ? "true" : undefined}
          aria-disabled={isDisabled ? "true" : undefined}
          data-slot="rating-input"
          data-disabled={isDisabled ? "true" : undefined}
          data-invalid={isInvalid ? "true" : undefined}
          onKeyDown={handleKeyDown}
          onMouseLeave={handleItemHoverLeave}
          className={cn(
            "relative inline-flex items-center gap-1 select-none",
            isDisabled && "opacity-40 pointer-events-none cursor-not-allowed",
            className
          )}
          {...props}
        >
          {children ||
            items.map((ratingVal) => {
              const label = labels?.[ratingVal - 1];
              const computedAria = getItemAriaLabel
                ? getItemAriaLabel(ratingVal, max, label)
                : label
                ? `${ratingVal} of ${max} stars, ${label}`
                : `${ratingVal} of ${max} stars`;

              return (
                <RatingInputItem
                  key={ratingVal}
                  value={ratingVal}
                  aria-label={computedAria}
                  isRovingActive={activeTabIndex === ratingVal}
                />
              );
            })}
        </div>
      </RatingInputContext.Provider>
    );
  }
);

/* -------------------------------------------------------------------------- */
/* RatingInputItem                                                            */
/* -------------------------------------------------------------------------- */

export interface RatingInputItemProps
  extends Omit<React.ComponentPropsWithoutRef<"button">, "value"> {
  /**
   * The 1-based rating score this item represents.
   */
  value: number;
  /**
   * Whether this item is the designated roving tab stop (tabIndex=0).
   */
  isRovingActive?: boolean;
}

export const RatingInputItem = React.forwardRef<HTMLButtonElement, RatingInputItemProps>(
  function RatingInputItem(
    { value: itemValue, isRovingActive, className, "aria-label": ariaLabel, ...props },
    ref
  ) {
    const ctx = useRatingInputContext();

    // Cumulative fill calculation:
    // If hovering, preview fills up to hoveredValue. Otherwise fills up to committed value.
    const effectiveRating = ctx.hoveredValue !== null ? ctx.hoveredValue : (ctx.value ?? 0);
    const isFilled = itemValue <= effectiveRating;
    const isCommitted = ctx.value === itemValue;
    const isFocused = ctx.focusedIndex === itemValue;

    // Hit target and icon size metrics
    const sizeConfig = {
      sm: { hit: "w-8 h-8", icon: 16 },
      md: { hit: "w-10 h-10", icon: 20 },
      lg: { hit: "w-12 h-12", icon: 24 },
    }[ctx.size];

    return (
      <button
        ref={ref}
        type="button"
        role="radio"
        tabIndex={isRovingActive ? 0 : -1}
        aria-checked={isCommitted}
        aria-posinset={itemValue}
        aria-setsize={ctx.max}
        aria-label={ariaLabel ?? `${itemValue} of ${ctx.max} stars`}
        disabled={ctx.disabled}
        data-slot="rating-item"
        data-rating-value={itemValue}
        data-filled={isFilled ? "true" : "false"}
        data-committed={isCommitted ? "true" : "false"}
        onClick={() => ctx.onItemSelect(itemValue)}
        onMouseEnter={() => ctx.onItemHover(itemValue)}
        onFocus={() => ctx.onItemFocus(itemValue)}
        onBlur={ctx.onItemBlur}
        className={cn(
          "relative inline-flex items-center justify-center rounded-xl p-0 transition-transform duration-100 ease-out outline-none",
          sizeConfig.hit,
          // Touch target padding without bloating icon SVG visually
          "focus-visible:ring-2 focus-visible:ring-[var(--halo-focus-color)] focus-visible:ring-offset-2 halo-focus-ring",
          !ctx.disabled && !ctx.readOnly && "cursor-pointer active:scale-90 hover:scale-110",
          ctx.disabled && "cursor-not-allowed",
          className
        )}
        {...props}
      >
        <HaloIcon
          icon={ctx.icon || StarIcon}
          size={sizeConfig.icon}
          className={cn(
            "transition-all duration-150 ease-out",
            isFilled
              ? "text-amber-400 dark:text-amber-300 [&_path]:fill-amber-400 dark:[&_path]:fill-amber-300 [&_path]:stroke-amber-400 dark:[&_path]:stroke-amber-300 filter drop-shadow-[0_1px_4px_rgba(251,191,36,0.3)]"
              : "text-muted-foreground/35 [&_path]:fill-transparent [&_path]:stroke-muted-foreground/50 hover:text-muted-foreground/60"
          )}
        />
      </button>
    );
  }
);

@import "./halo-material.css";

/**
 * HaloUI Liquid Material Design System Tokens
 * Physical optical material engine: refraction, specular highlight, optical edges,
 * neoskeuomorphic depth, tactile compression, and virtual directional lighting.
 */

:root {
  /* Surfaces (Flat & Structural) */
  --halo-surface: #ffffff;
  --halo-surface-muted: #f4f5f7;
  --halo-surface-elevated: #ffffff;
  --halo-surface-inset: #f8f9fb;
  --halo-surface-recessed: #f1f2f5;

  /* Borders */
  --halo-border: #d2d6dc;
  --halo-border-subtle: #e5e7eb;
  --halo-border-strong: #9ca3af;

  /* Tactile Controls: Neutral / Default */
  --halo-control-top: #ffffff;
  --halo-control-bottom: #f3f4f6;
  --halo-control-border: #d1d5db;
  --halo-control-depth: #cbd1d8;
  --halo-control-highlight: rgba(255, 255, 255, 0.9);
  --halo-control-text: #111827;

  /* Primary Action (Neutral Monochrome Tactile) */
  --halo-primary-top: #18191d;
  --halo-primary-bottom: #0f1013;
  --halo-primary-border: #23252a;
  --halo-primary-depth: #050507;
  --halo-primary-highlight: rgba(255, 255, 255, 0.22);
  --halo-primary-foreground: #ffffff;
  --halo-primary-hover-top: #24262c;
  --halo-primary-hover-bottom: #14161a;

  /* Secondary Action */
  --halo-secondary-top: #ffffff;
  --halo-secondary-bottom: #f4f5f7;
  --halo-secondary-border: #d1d5db;
  --halo-secondary-depth: #cbd1d8;
  --halo-secondary-highlight: rgba(255, 255, 255, 0.85);
  --halo-secondary-foreground: #1f2937;

  /* Destructive Action */
  --halo-destructive-top: #e53935;
  --halo-destructive-bottom: #d32f2f;
  --halo-destructive-border: #b71c1c;
  --halo-destructive-depth: #8b0000;
  --halo-destructive-highlight: rgba(255, 255, 255, 0.28);
  --halo-destructive-foreground: #ffffff;

  /* Inset Inputs & Wells */
  --halo-input-background: #ffffff;
  --halo-input-border: #d1d5db;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.08);

  /* Elevated Overlays & Pop Cards (Apple iOS / macOS frosted liquid glass with high legibility - not too transparent) */
  --halo-elevated-background: rgba(255, 255, 255, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.85);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);
  --halo-glass-pop-background: rgba(255, 255, 255, 0.92);
  --halo-glass-pop-border: rgba(255, 255, 255, 0.85);
  --halo-glass-pop-blur: 20px;
  --halo-glass-pop-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);

  /* Corner Radii */
  --halo-radius-xs: 6px;
  --halo-radius-sm: 8px;
  --halo-radius-control: 11px;
  --halo-radius-md: 12px;
  --halo-radius-lg: 16px;
  --halo-radius-xl: 20px;
  --halo-radius-full: 9999px;

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #0284c7;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Motion Presets & Timing Architecture */
  --halo-duration-micro: 80ms;
  --halo-duration-press: 80ms;
  --halo-duration-state: 140ms;
  --halo-duration-reveal: 180ms;
  --halo-duration-settle: 240ms;
  --halo-ease-tactile: cubic-bezier(0.2, 0.8, 0.3, 1);
  --halo-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --halo-ease-out: cubic-bezier(0, 0, 0.2, 1);

  /* Typography & Canvas */
  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;

  /* Backward Compatibility Bridges */
  --halo-edge: rgba(0, 0, 0, 0.1);
  --halo-edge-soft: rgba(0, 0, 0, 0.05);
  --halo-edge-bright: rgba(255, 255, 255, 0.9);
  --halo-edge-inner: inset 0 1px 0 rgba(255, 255, 255, 0.85);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.08);
  --halo-highlight: linear-gradient(180deg, rgba(255, 255, 255, 0.35) 0%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;
  --halo-shadow-contact: 0 1px 2px rgba(0, 0, 0, 0.06);
  --halo-shadow-elevated: 0 1px 2px rgba(0, 0, 0, 0.06), 0 8px 24px rgba(0, 0, 0, 0.08);
  --halo-shadow-ambient: 0 12px 28px rgba(0, 0, 0, 0.08);
  --halo-shadow-compressed: inset 0 1px 2px rgba(0, 0, 0, 0.12);
  --halo-blur-sm: 0px;
  --halo-blur-md: 0px;
  --halo-blur-lg: 0px;
  --halo-blur-xl: 0px;
  --halo-refraction-strength: 0;
  --halo-refraction-offset: 0;
  --halo-noise-opacity: 0;
  --halo-glow: transparent;
}

.dark {
  /* Surfaces (Dark Mode: Solid graphite/slate) */
  --halo-surface: #14161a;
  --halo-surface-muted: #1c1e24;
  --halo-surface-elevated: #1e2027;
  --halo-surface-inset: #0e0f13;
  --halo-surface-recessed: #181920;

  /* Borders */
  --halo-border: #30343f;
  --halo-border-subtle: #252831;
  --halo-border-strong: #4a5061;

  /* Tactile Controls: Neutral / Default */
  --halo-control-top: #262930;
  --halo-control-bottom: #1c1e24;
  --halo-control-border: #383c46;
  --halo-control-depth: #111317;
  --halo-control-highlight: rgba(255, 255, 255, 0.14);
  --halo-control-text: #f3f4f6;

  /* Primary Action (High-Contrast White in Dark Mode) */
  --halo-primary-top: #ffffff;
  --halo-primary-bottom: #f1f2f4;
  --halo-primary-border: #e2e4e9;
  --halo-primary-depth: #c4c8d0;
  --halo-primary-highlight: rgba(255, 255, 255, 1);
  --halo-primary-foreground: #0f1013;
  --halo-primary-hover-top: #ffffff;
  --halo-primary-hover-bottom: #e5e7eb;

  /* Secondary Action */
  --halo-secondary-top: #262930;
  --halo-secondary-bottom: #1c1e24;
  --halo-secondary-border: #383c46;
  --halo-secondary-depth: #111317;
  --halo-secondary-highlight: rgba(255, 255, 255, 0.14);
  --halo-secondary-foreground: #f3f4f6;

  /* Destructive Action */
  --halo-destructive-top: #dc2626;
  --halo-destructive-bottom: #b91c1c;
  --halo-destructive-border: #991b1b;
  --halo-destructive-depth: #450a0a;
  --halo-destructive-highlight: rgba(255, 255, 255, 0.22);
  --halo-destructive-foreground: #ffffff;

  /* Inset Inputs & Wells */
  --halo-input-background: #0e0f13;
  --halo-input-border: #30343f;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.4);

  /* Elevated Overlays & Pop Cards (Apple iOS / macOS frosted liquid glass with high legibility - not too transparent) */
  --halo-elevated-background: rgba(22, 24, 30, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.15);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.22), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.70), 0 20px 48px -6px rgba(0, 0, 0, 0.65), 0 6px 16px rgba(0, 0, 0, 0.50);
  --halo-glass-pop-background: rgba(22, 24, 30, 0.92);
  --halo-glass-pop-border: rgba(255, 255, 255, 0.15);
  --halo-glass-pop-blur: 20px;
  --halo-glass-pop-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.22), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.70), 0 20px 48px -6px rgba(0, 0, 0, 0.65), 0 6px 16px rgba(0, 0, 0, 0.50);

  /* Focus Ring Tokens */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;

  /* Backward Compatibility Bridges */
  --halo-edge: rgba(255, 255, 255, 0.12);
  --halo-edge-soft: rgba(255, 255, 255, 0.05);
  --halo-edge-bright: rgba(255, 255, 255, 0.22);
  --halo-edge-inner: inset 0 1px 0 rgba(255, 255, 255, 0.14);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);
  --halo-highlight: linear-gradient(180deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;
  --halo-shadow-contact: 0 1px 2px rgba(0, 0, 0, 0.4);
  --halo-shadow-elevated: 0 1px 2px rgba(0, 0, 0, 0.4), 0 8px 24px rgba(0, 0, 0, 0.55);
  --halo-shadow-ambient: 0 16px 36px rgba(0, 0, 0, 0.6);
  --halo-shadow-compressed: inset 0 1px 2px rgba(0, 0, 0, 0.5);
  --halo-blur-sm: 0px;
  --halo-blur-md: 0px;
  --halo-blur-lg: 0px;
  --halo-blur-xl: 0px;
  --halo-refraction-strength: 0;
  --halo-refraction-offset: 0;
  --halo-noise-opacity: 0;
  --halo-glow: transparent;
}

/* Explicit Stage Scopes for Interactive Previews */
.light,
[data-stage-theme="light"] {
  --halo-surface: #ffffff;
